+func TestInstanceMetadataClientIsAvailable(t *testing.T) {
+	for _, tc := range []struct {
+		name      string
+		id        string
+		available bool
+	}{
+		{name: "short ID", id: "i-1a2b3c4d", available: true},
+		{name: "long ID", id: "i-1234567890abcdef0", available: true},
+		{name: "HTML response", id: "<html>Login</html>"},
+		{name: "extra characters", id: "i-12345678\n"},
+		{name: "wrong length", id: "i-123456789"},
+		{name: "uppercase", id: "i-ABCDEF12"},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+				switch {
+				case r.Method == http.MethodPut && r.URL.Path == "/latest/api/token":
+					_, _ = w.Write([]byte("token"))
+				case r.Method == http.MethodGet && r.URL.Path == "/latest/meta-data/instance-id":
+					_, _ = w.Write([]byte(tc.id))
+				default:
+					t.Errorf("unexpected metadata request: %s %s", r.Method, r.URL.Path)
+					http.NotFound(w, r)
+				}
+			}))
+			defer server.Close()
+
+			client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imds.New(imds.Options{Endpoint: server.URL})))
+			require.NoError(t, err)
+			assert.Equal(t, tc.available, client.IsAvailable(context.Background()))
+		})
+	}
+}
